css:
.loader { position: relative; display: inline-block; width: var(--loader-size); height: var(--loader-size); border-radius: calc(var(--loader-size) * .2); border: calc(var(--loader-size) * .07) solid var(--loader-color); box-sizing: border-box; animation: twBoxPop calc(var(--loader-speed) * 2) ease-in-out infinite; }
.loader .tick { position: absolute; left: 26%; top: 16%; width: 32%; height: 54%; border-right: calc(var(--loader-size) * .09) solid var(--loader-color); border-bottom: calc(var(--loader-size) * .09) solid var(--loader-color); animation: twTick calc(var(--loader-speed) * 2) ease-in-out infinite; }
@keyframes twBoxPop { 0%, 100% { transform: scale(1); } 45% { transform: scale(1.1); } }
@keyframes twTick { 0%, 15% { opacity: 0; transform: rotate(45deg) scale(.2); } 45%, 80% { opacity: 1; transform: rotate(45deg) scale(1); } 100% { opacity: 0; transform: rotate(45deg) scale(.2); } }
